	@Test
	void alreadyTrackedNarrowedRequestAndGraphFrameSurviveEntryAndReentry() {
		BindingSet hiddenRequest = BindingSetOrigin.optimizationInput(binding(INPUT, REQUEST_VALUE));
		QueryBindingSet narrowed = new QueryBindingSet();
		BindingSetOrigin.set(narrowed, BindingSetOrigin.of(hiddenRequest));
		QueryBindingSet graphSource = new QueryBindingSet();
		GraphFrameBindings.supply(graphSource, PRIVATE_GRAPH, GRAPH_VALUE);
		GraphFrameBindings.preserve(graphSource, narrowed);

		assertFalse(narrowed.hasBinding(INPUT));
		assertFalse(narrowed.hasBinding(PRIVATE_GRAPH));
		assertTrue(BindingSetOrigin.isTrackedInput(narrowed));
		assertSame(REQUEST_VALUE, BindingSetOrigin.of(narrowed).parameterValue(INPUT));
		assertSame(GRAPH_VALUE,
				GraphFrameBindings.from(narrowed).retainedParametersForTransport().get(PRIVATE_GRAPH));
		assertTrue(GraphFrameBindings.isSupplied(graphSource, PRIVATE_GRAPH),
				"the retained descriptor came from a real internally supplied graph mapping");

		assertSame(narrowed, BindingSetOrigin.requestInput(narrowed),
				"re-entering a narrowed tracked frame must not reinterpret it as raw caller input");
		BindingSet entered = rootEntry(narrowed);
		assertSame(narrowed, entered);
		assertSame(REQUEST_VALUE, BindingSetOrigin.of(entered).parameterValue(INPUT));
		assertSame(GRAPH_VALUE,
				GraphFrameBindings.from(entered).retainedParametersForTransport().get(PRIVATE_GRAPH));

		BindingSet materialized = BindingSetOrigin.materializeParameters(entered,
				List.of(Var.of(INPUT, REQUEST_VALUE, false, false)), new QueryEvaluationContext.Minimal(null));
		assertTrue(materialized.hasBinding(INPUT));
		assertSame(REQUEST_VALUE, materialized.getValue(INPUT));
		assertSame(GRAPH_VALUE,
				GraphFrameBindings.from(materialized).retainedParametersForTransport().get(PRIVATE_GRAPH),
				"materializing a hidden request parameter must retain the independent narrowed GRAPH frame");
	}

	@Test
	void emptyOverlaysPreserveTargetAuthorityAcrossLaterRequestEntry() {
		BindingSet hiddenSource = BindingSetOrigin.optimizationInput(binding(INPUT, REQUEST_VALUE));

		QueryBindingSet blankTarget = new QueryBindingSet();
		blankTarget.addAll(hiddenSource);
		BindingSet blankReentry = BindingSetOrigin.requestInput(blankTarget);

		QueryBindingSet occupiedUntracked = new QueryBindingSet();
		occupiedUntracked.setBinding(INPUT, OUTPUT_VALUE);
		occupiedUntracked.addAll(hiddenSource);
		BindingSet occupiedReentry = BindingSetOrigin.requestInput(occupiedUntracked);
		BindingSet occupiedParameters = BindingSetOrigin.optimizationInput(occupiedReentry);

		QueryBindingSet occupiedLocal = new QueryBindingSet(
				BindingSetOrigin.produced(binding(INPUT, OUTPUT_VALUE), Set.of(INPUT)));
		occupiedLocal.addAll(hiddenSource);
		BindingSet localReentry = BindingSetOrigin.requestInput(occupiedLocal);

		BindingSet oldRequest = BindingSetOrigin.optimizationInput(binding(INPUT, OUTPUT_VALUE));
		QueryBindingSet occupiedRequest = new QueryBindingSet(oldRequest);
		occupiedRequest.addAll(hiddenSource);

		String[] names = { INPUT };
		ArrayBindingSet hiddenArraySource = new ArrayBindingSet(hiddenSource, Set.of(INPUT), names);
		ArrayBindingSet blankArray = new ArrayBindingSet(INPUT);
		blankArray.addAll(hiddenArraySource);
		ArrayBindingSet occupiedUntrackedArray = new ArrayBindingSet(INPUT);
		occupiedUntrackedArray.setBinding(INPUT, OUTPUT_VALUE);
		occupiedUntrackedArray.addAll(hiddenArraySource);
		BindingSet arrayReentry = BindingSetOrigin.requestInput(occupiedUntrackedArray);
		BindingSet arrayParameters = BindingSetOrigin.optimizationInput(arrayReentry);
		ArrayBindingSet occupiedLocalArray = new ArrayBindingSet(
				BindingSetOrigin.produced(binding(INPUT, OUTPUT_VALUE), Set.of(INPUT)), Set.of(INPUT), names);
		occupiedLocalArray.addAll(hiddenArraySource);

		assertAll("a zero-mapping source cannot become target provenance or replace later entry values",
				() -> assertFalse(BindingSetOrigin.isTrackedInput(blankTarget)),
				() -> assertFalse(BindingSetOrigin.isTrackedInput(blankReentry)),
				() -> assertSame(OUTPUT_VALUE, occupiedUntracked.getValue(INPUT)),
				() -> assertFalse(BindingSetOrigin.isTrackedInput(occupiedUntracked)),
				() -> assertTrue(BindingSetOrigin.of(occupiedReentry).isRequest(INPUT)),
				() -> assertSame(OUTPUT_VALUE, BindingSetOrigin.of(occupiedParameters).parameterValue(INPUT)),
				() -> assertSame(OUTPUT_VALUE, occupiedLocal.getValue(INPUT)),
				() -> assertTrue(BindingSetOrigin.of(localReentry).isLocal(INPUT)),
				() -> assertFalse(BindingSetOrigin.of(localReentry).isRequest(INPUT)),
				() -> assertSame(OUTPUT_VALUE, BindingSetOrigin.of(occupiedRequest).parameterValue(INPUT)),
				() -> assertFalse(BindingSetOrigin.isTrackedInput(blankArray)),
				() -> assertSame(OUTPUT_VALUE, occupiedUntrackedArray.getValue(INPUT)),
				() -> assertFalse(BindingSetOrigin.isTrackedInput(occupiedUntrackedArray)),
				() -> assertTrue(BindingSetOrigin.of(arrayReentry).isRequest(INPUT)),
				() -> assertSame(OUTPUT_VALUE, BindingSetOrigin.of(arrayParameters).parameterValue(INPUT)),
				() -> assertTrue(BindingSetOrigin.of(occupiedLocalArray).isLocal(INPUT)),
				() -> assertFalse(BindingSetOrigin.of(occupiedLocalArray).isRequest(INPUT)));
	}

	@Test
	void evaluationKeysHandleDeepProducerChainsWithoutLosingHiddenRequestAuthority() {
		MapBindingSet request = new MapBindingSet(2);
		request.addBinding(INPUT, REQUEST_VALUE);
		request.addBinding(PAYLOAD, OUTPUT_VALUE);
		BindingSetOrigin origin = BindingSetOrigin.of(BindingSetOrigin.optimizationInput(request));
		int depth = 65_536;
		for (int i = 0; i < depth; i++) {
			origin = origin.producing(Set.of("layer" + i));
		}

		BindingSetOrigin.OriginKey key = origin.key(Set.of(INPUT, PAYLOAD, "layer0", "layer65535"));

		assertEquals(Set.of(INPUT, PAYLOAD), key.requests());
		assertEquals(Set.of("layer0", "layer65535"), key.locals());
		assertSame(REQUEST_VALUE, key.parameters().get(INPUT));
		assertSame(OUTPUT_VALUE, key.parameters().get(PAYLOAD));
	}

	@Test
	void evaluationKeyPreservesDeepProducerMasksAndHiddenRequestRepresentative() {
		MapBindingSet request = new MapBindingSet(2);
		request.addBinding(INPUT, REQUEST_VALUE);
		request.addBinding(PAYLOAD, OUTPUT_VALUE);
		BindingSetOrigin origin = BindingSetOrigin.of(BindingSetOrigin.optimizationInput(request));
		int depth = 8_192;
		for (int i = 0; i < depth; i++) {
			origin = origin.producing(i == depth / 2 ? Set.of("layer" + i, INPUT) : Set.of("layer" + i));
		}

		BindingSetOrigin.OriginKey key = origin.key(Set.of(INPUT, PAYLOAD, "layer0", "layer8191"));

		assertEquals(Set.of(PAYLOAD), key.requests());
		assertEquals(Set.of(INPUT, "layer0", "layer8191"), key.locals());
		assertNull(key.parameters().get(INPUT));
		assertSame(OUTPUT_VALUE, key.parameters().get(PAYLOAD));
	}

	@Test
	void deepProducerAuthoritySurvivesARealPhysicalSpill() {
		Value representative = SimpleValueFactory.getInstance().createLiteral("retained", "EN");
		MapBindingSet request = new MapBindingSet(2);
		request.addBinding(INPUT, REQUEST_VALUE);
		request.addBinding(PAYLOAD, representative);
		BindingSetOrigin origin = BindingSetOrigin.of(BindingSetOrigin.optimizationInput(request));
		Set<String> repeatedLocal = Set.of("deepLocal");
		for (int i = 0; i < 65_536; i++) {
			origin = origin.producing(repeatedLocal);
		}
		origin = origin.producing(Set.of(INPUT));
		QueryBindingSet row = new QueryBindingSet();
		row.setBinding(INPUT, GRAPH_VALUE);
		BindingSetOrigin.set(row, origin);

		try (var spill = new BindingSetSpillFile("rdf4j-origin-depth-", "origin depth regression")) {
			assertTrue(spill.write(row));
			assertTrue(spill.finishWriting());
			try (var rows = spill.openReader()) {
				BindingSet restored = rows.next();
				BindingSetOrigin restoredOrigin = BindingSetOrigin.of(restored);
				assertEquals(GRAPH_VALUE, restored.getValue(INPUT));
				assertTrue(restoredOrigin.isLocal(INPUT));
				assertFalse(restoredOrigin.isRequest(INPUT));
				assertNull(restoredOrigin.parameterValue(INPUT));
				assertEquals(REQUEST_VALUE, restoredOrigin.retainedParametersForTransport().get(INPUT));
				Literal restoredPayload = (Literal) restoredOrigin.parameterValue(PAYLOAD);
				Literal retainedPayload = (Literal) restoredOrigin.retainedParametersForTransport().get(PAYLOAD);
				assertEquals("EN", restoredPayload.getLanguage().orElseThrow());
				assertEquals("EN", retainedPayload.getLanguage().orElseThrow());
				assertTrue(restoredOrigin.isLocal("deepLocal"));
				assertTrue(restoredOrigin.isRequest(PAYLOAD));
				assertNull(rows.next());
			}
		}
	}

	@Test
	void newLocalMappingWritePreservesUnrelatedHiddenParametersAndGraphAuthority() {
		MapBindingSet request = new MapBindingSet(2);
		request.addBinding(INPUT, REQUEST_VALUE);
		request.addBinding(PAYLOAD, OUTPUT_VALUE);
		BindingSet hidden = BindingSetOrigin.optimizationInput(request);
		QueryBindingSet target = new QueryBindingSet(hidden);
		GraphFrameBindings.supply(target, PRIVATE_GRAPH, GRAPH_VALUE);
		BindingSet source = BindingSetOrigin.produced(binding("newLocal", OUTPUT_VALUE), Set.of("newLocal"));

		target.addAll(source);

		BindingSetOrigin origin = BindingSetOrigin.of(target);
		assertSame(OUTPUT_VALUE, target.getValue("newLocal"));
		assertTrue(origin.isLocal("newLocal"));
		assertFalse(origin.isRequest("newLocal"));
		assertNull(origin.parameterValue("newLocal"));
		assertFalse(target.hasBinding(INPUT));
		assertFalse(target.hasBinding(PAYLOAD));
		assertTrue(origin.isRequest(INPUT));
		assertTrue(origin.isRequest(PAYLOAD));
		assertSame(REQUEST_VALUE, origin.parameterValue(INPUT));
		assertSame(OUTPUT_VALUE, origin.parameterValue(PAYLOAD));
		assertTrue(GraphFrameBindings.isSupplied(target, PRIVATE_GRAPH));
		assertSame(GRAPH_VALUE,
				GraphFrameBindings.from(target).retainedParametersForTransport().get(PRIVATE_GRAPH));

		String[] arrayNames = { INPUT, PAYLOAD, "newLocal", PRIVATE_GRAPH };
		ArrayBindingSet arrayTarget = new ArrayBindingSet(hidden,
				Set.of(INPUT, PAYLOAD, "newLocal", PRIVATE_GRAPH), arrayNames);
		GraphFrameBindings.supply(arrayTarget, PRIVATE_GRAPH, GRAPH_VALUE);
		ArrayBindingSet arraySource = new ArrayBindingSet(source, Set.of("newLocal"), new String[] { "newLocal" });
		arrayTarget.addAll(arraySource);
		BindingSetOrigin arrayOrigin = BindingSetOrigin.of(arrayTarget);
		assertSame(OUTPUT_VALUE, arrayTarget.getValue("newLocal"));
		assertTrue(arrayOrigin.isLocal("newLocal"));
		assertTrue(arrayOrigin.isRequest(INPUT));
		assertSame(REQUEST_VALUE, arrayOrigin.parameterValue(INPUT));
		assertSame(OUTPUT_VALUE, arrayOrigin.parameterValue(PAYLOAD));
		assertTrue(GraphFrameBindings.isSupplied(arrayTarget, PRIVATE_GRAPH));
		assertSame(GRAPH_VALUE,
				GraphFrameBindings.from(arrayTarget).retainedParametersForTransport().get(PRIVATE_GRAPH));
	}

